mapper.update:
update base_permission set pid = #{pid}, order_id = (
select t.* from (select ifnull(max(order_id) + 1, 1) from base_permission where pid = #{pid} and del_flag = 0) t
) where id = #{id} and del_flag = 0

mapper.select:
select distinct zp.order_id,zp.id,zp.pid,zp.name,zp.level,zp.link,zp.status,zp.icon from zzccaidp_permission zp, zzccaidp_role_permission zrp where zp.id=zrp.permission_id and zp.del_flag = 0 and zp.status = 0 and zp.`type` in (1,2) and zrp.role_id in
#{roleId}
order by zp.order_id
